def flatten(report):
 fm=report.get('factMap',{}) or {}
 order=(report.get('reportMetadata',{}) or {}).get('detailColumns',[]) or []
 info=(report.get('reportExtendedMetadata',{}) or {}).get('detailColumnInfo',{}) or {}
 lab=lambda k:(info.get(k,{}) or {}).get('label',k)
 out=[]
 for k,node in fm.items():
  if not str(k).endswith('!T'): continue
  for r in (node.get('rows') or []):
   cells=r.get('dataCells') or []
   out.append({lab(order[i]):(((cells[i].get('label') if isinstance(cells[i],dict) else None) or (cells[i].get('value') if isinstance(cells[i],dict) else cells[i])) if i<len(cells) else None) for i in range(len(order))})
 return out
